{'id': 'u6', 'title': 'Parametric 3D Modeling', 'weeks': 'Weeks 8–9',
 'summary': 'Build solid models from constrained sketches and features in Onshape or FreeCAD, and make them easy to change.',
 'objectives': ['Create fully constrained 2D sketches.', 'Use extrude, revolve, fillet, chamfer, hole, shell and pattern features.', 'Drive models with variables and equations (design intent).', 'Compute mass properties and use them in design.'],
 'concepts': ['A parametric model is a recipe: sketches plus features in a history tree. Change a dimension and the model rebuilds.',
              'A sketch is fully constrained when geometric constraints (parallel, tangent, coincident) and dimensions fix every degree of freedom. Each free 2D point has 2 degrees of freedom.',
              'Design intent: dimension the way the part functions. If holes must stay centered, constrain them to the midpoint, not to an edge.',
              'Variables (Onshape) and spreadsheets or expressions (FreeCAD) let one number drive many features.',
              'CAD computes volume, mass, center of mass and moments of inertia from the material density.'],
 'eqs': [('m=\\rho V', 'Mass from volume'), ('\\text{DOF}_{sketch}=2n_{pts}-\\sum\\text{constraints}', 'Sketch degrees of freedom (points only)'), ('V_{rev}=2\\pi\\bar r A', 'Pappus: volume of revolution')],
 'worked': [
  {'q': 'An aluminum plate is 100 × 60 × 5 mm with four Ø6 through holes. Find its mass (ρ = 2.70 g/cm³).', 'steps': ['V = 100 × 60 × 5 − 4 × π × 3² × 5 = 30,000 − 565.5 = 29,434.5 mm³.', 'm = 29.43 cm³ × 2.70.'], 'a': '≈ 79.5 g.'},
  {'q': 'A rectangle drawn with the rectangle tool has 4 corner points (8 DOF) and comes with 2 horizontal and 2 vertical constraints. How many more dimensions or constraints fully constrain it?', 'steps': ['8 − 4 = 4 DOF remain: width, height, and x and y position.', 'Add width and height, then make one corner coincident with the origin (removes 2).'], 'a': '4 more: two dimensions plus two for position (e.g. a corner coincident with the origin).'},
  {'q': 'A ring is made by revolving a 10 × 4 mm rectangle whose centroid is 25 mm from the axis. Find its volume.', 'steps': ['A = 40 mm².', 'V = 2π × 25 × 40.'], 'a': '≈ 6,283 mm³ (6.28 cm³).'}],
 'practice': [('A steel block 50 × 50 × 20 mm (ρ = 7.85 g/cm³). Mass?', '50 cm³ × 7.85 ≈ 392.5 g.'), ('Why fully constrain sketches?', 'So changes rebuild predictably; under-constrained sketches shift when edited.'),
              ('A PLA cube 20 mm on a side, solid (ρ = 1.24 g/cm³). Mass?', '8 cm³ × 1.24 ≈ 9.9 g.')],
 'misc': [('A model that looks right is right.', 'Check for under-constrained sketches and fragile references; they break on edits.'), ('Dimension from whatever edge is handy.', 'Dimension from functional datums to capture intent.'),
          ('Mass properties are exact.', 'Only as good as the density and model you enter.')],
 'quiz': [{'q': 'A fully constrained sketch has…', 'opts': ['no dimensions', 'zero remaining DOF', 'only constraints', 'only dimensions'], 'ok': 1, 'why': 'Every DOF fixed.'},
          {'q': 'The history tree records…', 'opts': ['emails', 'the sequence of features', 'materials only', 'render settings'], 'ok': 1, 'why': 'The parametric recipe.'},
          {'q': 'Revolving area A at centroid radius r̄ gives volume…', 'opts': ['πr̄A', '2πr̄A', 'r̄A', '2πA'], 'ok': 1, 'why': 'Pappus’s theorem.'},
          {'q': 'Onshape runs…', 'opts': ['only on Linux', 'in a web browser', 'only offline', 'on phones only'], 'ok': 1, 'why': 'Cloud-native CAD.'}],
 'cards': [('Parametric model', 'Features driven by editable dimensions.'), ('Constraint', 'Geometric relationship, e.g. tangent.'), ('Design intent', 'Model behaves as the function requires.'), ('Feature', 'Extrude, revolve, fillet, hole, pattern…'),
           ('History tree', 'Ordered list of features.'), ('Mass properties', 'Volume, mass, center of mass, inertia.')],
 'planet': {'text': ['Parametric models make it cheap to try lighter versions: change a wall thickness variable and the whole part updates, with its new mass. That turns lightweighting from guesswork into a quick study (Lab D).',
                     'Onshape’s Free plan and FreeCAD put professional modeling in anyone’s hands, so open-source designs for repair parts and appropriate technology can be shared and improved.'],
            'site': [('Intro to Aerospace Engineering', 'Intro_to_Aerospace_Engineering.html')],
            'src': [_OSF, _FC]},
 'res': [(_OSL[0], _OSL[1], 'Free self-paced modeling courses.'), (_FCG[0], _FCG[1], 'FreeCAD Part Design basics.'), (_OSF[0], _OSF[1], 'Sign up for the Free plan.')]},

{'id': 'u7', 'title': 'Assemblies & Drawings', 'weeks': 'Weeks 10–11',
 'summary': 'Put parts together with mates, check motion and interference, and produce drawings someone can build from.',
 'objectives': ['Assemble parts with mates (fastened, revolute, slider) and count degrees of freedom.', 'Check interference and clearance.', 'Produce detail and assembly drawings with a title block, bill of materials and balloons.', 'Use Gruebler’s equation for planar mechanisms.'],
 'concepts': ['A free rigid body has 6 degrees of freedom (3 translations, 3 rotations). A revolute mate leaves 1; a slider leaves 1; a fastened mate leaves 0.',
              'Bottom-up assembly inserts finished parts; top-down designs parts in context of the assembly.',
              'A planar mechanism’s mobility is M = 3(n − 1) − 2j₁ − j₂ (Gruebler), with n links including ground, j₁ full joints and j₂ half joints.',
              'Drawings come from the model: views, sections, dimensions and notes, a title block (part, material, scale, projection symbol, units, tolerances) and, for assemblies, a bill of materials (BOM) with balloons.',
              'Interference checks catch parts that overlap before anything is made.'],
 'eqs': [('M=3(n-1)-2j_1-j_2', 'Gruebler’s equation (planar)'), ('\\text{DOF}_{3D}=6-\\text{removed}', 'Remaining DOF of a mated part')],
 'worked': [
  {'q': 'Find the mobility of a four-bar linkage (4 links including ground, 4 pin joints).', 'steps': ['M = 3(4 − 1) − 2(4) = 9 − 8.'], 'a': 'M = 1: one input drives it.'},
  {'q': 'A slider-crank: ground, crank, connecting rod, slider; 3 pins and 1 slider joint.', 'steps': ['n = 4, j₁ = 4 (pins and slider are full joints).', 'M = 9 − 8.'], 'a': 'M = 1, as in an engine.'},
  {'q': 'A BOM lists 4 × M5 screws at 1.2 g, 1 plate at 79.5 g and 2 brackets at 15.0 g. Total assembly mass?', 'steps': ['4.8 + 79.5 + 30.0.'], 'a': '114.3 g.'}],
 'practice': [('Mobility of 5 links, 5 pins?', 'M = 12 − 10 = 2.'), ('Mobility of 3 links, 3 pins?', 'M = 6 − 6 = 0: a rigid structure (a triangle).'),
              ('What must every title block state?', 'Part name/number, material, scale, units, projection method, general tolerances, author and revision.')],
 'misc': [('More mates are safer.', 'Redundant mates over-constrain and can fail to solve or hide errors.'), ('Assembly drawings need every dimension.', 'Detail drawings carry part dimensions; assembly drawings show how parts go together.'),
          ('If the model fits, the real parts will.', 'Only if tolerances are checked (Unit 5).')],
 'quiz': [{'q': 'A free rigid body in 3D has…', 'opts': ['3 DOF', '6 DOF', '1 DOF', '12 DOF'], 'ok': 1, 'why': '3 translations, 3 rotations.'},
          {'q': 'A four-bar linkage has mobility…', 'opts': ['0', '1', '2', '3'], 'ok': 1, 'why': 'Gruebler.'},
          {'q': 'A BOM lists…', 'opts': ['tolerances', 'parts and quantities', 'colors only', 'mates'], 'ok': 1, 'why': 'Bill of materials.'},
          {'q': 'A revolute mate leaves…', 'opts': ['0 DOF', '1 DOF', '2 DOF', '6 DOF'], 'ok': 1, 'why': 'One rotation.'}],
 'cards': [('Mate', 'Relationship that positions parts.'), ('Revolute', 'Pin joint; 1 rotational DOF.'), ('Gruebler', 'M = 3(n − 1) − 2j₁ − j₂.'), ('BOM', 'Bill of materials.'),
           ('Balloon', 'Numbered callout linking a part to the BOM.'), ('Title block', 'Drawing’s identity, scale, units and tolerances.')],
 'planet': {'text': ['A clear assembly drawing and BOM are a repair manual. Designs that use standard fasteners and can be taken apart are easier to fix, refurbish and recycle, which is a core idea of sustainable materials management.',
                     'Counting parts in the BOM is also a design-for-assembly check: fewer parts usually means less material, less energy and fewer failures.'],
            'site': [('Physics I', 'Physics_I.html')],
            'src': [_SMM, _FCG]},
 'res': [(_FCG[0], _FCG[1], 'FreeCAD assemblies and TechDraw.'), (_OSL[0], _OSL[1], 'Onshape assemblies and drawings.'), (_M2007[0], _M2007[1], 'Mechanisms in MIT 2.007.')]},

{'id': 'u8', 'title': '3D Printing & Design for Manufacture', 'weeks': 'Weeks 12–13',
 'summary': 'How parts are actually made, and how to design them so they are easy, cheap and low-waste to make, including 3D printing.',
 'objectives': ['Describe additive (3D printing), subtractive (machining) and forming processes.', 'Design for FDM printing: overhangs, supports, wall thickness, orientation.', 'Estimate print mass, filament length and time.', 'Apply design-for-manufacture and assembly (DFM/DFA) rules.'],
 'concepts': ['Additive manufacturing builds parts layer by layer; NIST works on measurement science and standards to make AM parts reliable. Machining removes material; molding and casting shape it.',
              'Fused-filament (FDM) printing: overhangs steeper than about 45° from vertical usually need supports; orient parts so loads do not pull layers apart, because layer bonds are the weak direction.',
              'Infill (often 10–20%) and a few perimeter walls make prints light; solid prints waste material and time.',
              'Filament length per gram = 1/(ρπr²). For 1.75 mm PLA (ρ = 1.24 g/cm³) that is about 33.5 cm per gram.',
              'DFM/DFA: fewer parts, standard features and fasteners, generous radii, self-locating features, and avoiding needlessly tight tolerances.'],
 'eqs': [('\\ell=\\frac{m}{\\rho\\,\\pi r^2}', 'Filament length for a print of mass m'), ('t\\approx\\frac{V}{w\\,h\\,v}', 'Print time from volume, line width w, layer height h and speed v')],
 'worked': [
  {'q': 'How much 1.75 mm PLA filament does a 10 g print use?', 'steps': ['Cross-section π(0.0875 cm)² = 0.02405 cm².', 'Length per gram = 1/(1.24 × 0.02405) = 33.5 cm.', '× 10.'], 'a': '≈ 3.35 m.'},
  {'q': 'Estimate print time for 10 g of PLA with a 0.4 mm line, 0.2 mm layers at 50 mm/s.', 'steps': ['V = 10/1.24 = 8.065 cm³ = 8,065 mm³.', 'Rate = 0.4 × 0.2 × 50 = 4 mm³/s.', 't = 8,065/4 = 2,016 s.'], 'a': '≈ 34 minutes of extrusion (real prints take longer due to travel moves).'},
  {'q': 'A 20 mm solid PLA cube weighs 9.9 g. At about 15% infill with walls, it weighs about 3.5 g. What fraction of material is saved?', 'steps': ['(9.9 − 3.5)/9.9.'], 'a': '≈ 65% less plastic (sample estimate; your slicer reports the real figure).'}],
 'practice': [('How many grams is 1 m of 1.75 mm PLA?', '100/33.5 ≈ 2.98 g.'), ('Why print a bracket so layers run along the load path?', 'Layer bonds are weaker than the extruded lines.'),
              ('Name two DFA rules.', 'Reduce part count; use self-locating features and standard fasteners.')],
 'misc': [('3D printing is always greener.', 'It can save material, but energy, failed prints and non-recycled waste matter; compare per part.'), ('Prints are as strong in every direction.', 'FDM parts are weakest between layers.'),
          ('100% infill is strongest so always best.', 'Walls carry most bending load; extra infill adds mass and time with little benefit.')],
 'quiz': [{'q': 'FDM parts are weakest…', 'opts': ['along the filament', 'between layers', 'at the surface', 'nowhere'], 'ok': 1, 'why': 'Layer adhesion.'},
          {'q': 'Overhangs beyond about 45° usually need…', 'opts': ['supports', 'more infill', 'faster speed', 'paint'], 'ok': 0, 'why': 'Nothing to print onto.'},
          {'q': 'Filament per gram for 1.75 mm PLA ≈', 'opts': ['3.4 cm', '33.5 cm', '3.35 m', '335 m'], 'ok': 1, 'why': '1/(ρπr²).'},
          {'q': 'A key DFA rule is…', 'opts': ['add parts', 'reduce part count', 'tighten all tolerances', 'use custom screws'], 'ok': 1, 'why': 'Fewer parts, fewer steps.'}],
 'cards': [('Additive manufacturing', 'Layer-by-layer building.'), ('FDM', 'Fused-filament 3D printing.'), ('Infill', 'Internal lattice percentage.'), ('Support', 'Temporary structure under overhangs.'),
           ('DFM', 'Design for manufacture.'), ('DFA', 'Design for assembly.')],
 'planet': {'text': ['Plastics are a large waste stream: EPA reports that U.S. plastics generation was 35.7 million tons in 2018, 12.2% of municipal solid waste, and only 8.7% was recycled. Designing prints with low infill, few supports and fewer failed attempts directly cuts that waste.',
                     'Additive manufacturing can place material only where loads need it, enabling lighter parts; NIST’s work aims to make those parts reliable enough for demanding uses.'],
            'site': [('Intro to Aerospace Engineering', 'Intro_to_Aerospace_Engineering.html')],
            'src': [_EPAP, _NAM]},
 'res': [(_NAM[0], _NAM[1], 'Standards and measurement for 3D printing.'), (_M2007[0], _M2007[1], 'Manufacturing processes.'), (_EPAP[0], _EPAP[1], 'Plastics data.')]},

{'id': 'u9', 'title': 'Design for Sustainability & Lightweighting', 'weeks': 'Week 14',
 'summary': 'Use your CAD skills to make parts lighter, longer-lasting and easier to repair and recycle, and estimate the payoff.',
 'objectives': ['Compare sections by mass and stiffness (second moment of area).', 'Estimate fuel and CO₂ savings from vehicle lightweighting.', 'Apply design-for-repair, disassembly and recycling principles.', 'Choose materials with their whole life cycle in mind.'],
 'concepts': ['Bending stiffness depends on EI. Moving material away from the neutral axis (tubes, I-beams) raises I with less mass.',
              'DOE reports that a 10% reduction in vehicle weight can improve fuel economy by 6–8%, and that lightweight materials can reduce component weight by 10–60% in the short term.',
              'EPA reports that every gallon of gasoline burned creates about 8,887 g of CO₂ (about 2.35 kg per liter).',
              'Design for disassembly: screws over glue, single materials where possible, and labeled plastics.',
              'Lightest is not always greenest: compare materials over the life cycle, including production energy and recyclability.'],
 'eqs': [('I_{rect}=\\frac{bh^3}{12},\\quad I_{tube}=\\frac{B^4-b^4}{12}', 'Second moment of area: solid and square tube'), ('\\Delta\\text{CO}_2=\\Delta\\text{fuel}\\times2.35\\ \\text{kg/L}', 'CO₂ from gasoline saved')],
 'worked': [
  {'q': 'Compare a solid 20 × 20 mm square bar with a 25 × 25 mm square tube with 2 mm walls: area (mass) and I.', 'steps': ['Bar: A = 400 mm², I = 20⁴/12 = 13,333 mm⁴.', 'Tube: A = 625 − 441 = 184 mm², I = (25⁴ − 21⁴)/12 = 16,345 mm⁴.'], 'a': 'The tube uses 54% less material and is 23% stiffer in bending.'},
  {'q': 'A 1,500 kg car is lightened by 10% (150 kg). It uses 8 L/100 km and drives 15,000 km a year. Using DOE’s 6–8%, estimate the fuel saved per year.', 'steps': ['Yearly fuel = 15,000/100 × 8 = 1,200 L.', '6%: 72 L; 8%: 96 L.'], 'a': 'About 72–96 L per year.'},
  {'q': 'Convert that to CO₂ with EPA’s 8,887 g per gallon.', 'steps': ['8.887 kg / 3.785 L = 2.35 kg/L.', '72 × 2.35 = 169; 96 × 2.35 = 225.'], 'a': '≈ 170–225 kg of CO₂ per car per year (a simplified estimate).'}],
 'practice': [('I of a solid 10 × 30 mm bar bending about its 10 mm-wide axis (h = 30)?', '10 × 30³/12 = 22,500 mm⁴.'), ('Same bar turned flat (h = 10, b = 30)?', '30 × 10³/12 = 2,500 mm⁴: 9 times less stiff.'),
              ('How many liters of gasoline make 1 tonne of CO₂?', '1,000/2.35 ≈ 426 L.')],
 'misc': [('Lighter always means greener.', 'Some light materials need much more energy to produce; judge over the life cycle.'), ('Stiffness depends only on the amount of material.', 'Where the material sits (I) matters more.'),
          ('Glue makes products better.', 'It often blocks repair and recycling.')],
 'quiz': [{'q': 'Bending stiffness depends on…', 'opts': ['E only', 'EI', 'mass only', 'color'], 'ok': 1, 'why': 'Modulus × second moment of area.'},
          {'q': 'DOE: 10% lighter vehicle → fuel economy improves…', 'opts': ['1–2%', '6–8%', '20–30%', '50%'], 'ok': 1, 'why': 'DOE figure.'},
          {'q': 'A gallon of gasoline burned makes about…', 'opts': ['889 g CO₂', '8,887 g CO₂', '88 kg CO₂', '2 g CO₂'], 'ok': 1, 'why': 'EPA figure.'},
          {'q': 'A design-for-disassembly choice is…', 'opts': ['adhesive everywhere', 'screws and single materials', 'mixed laminated plastics', 'welded covers'], 'ok': 1, 'why': 'Easier repair and recycling.'}],
 'cards': [('Second moment of area', 'I; geometric bending stiffness.'), ('Lightweighting', 'Removing mass without losing function.'), ('DOE rule', '10% lighter → 6–8% better fuel economy.'), ('Gasoline CO₂', '≈ 8,887 g/gal ≈ 2.35 kg/L.'),
           ('Design for disassembly', 'Easy to take apart for repair and recycling.'), ('Life cycle', 'Materials, making, use and end of life.')],
 'planet': {'text': ['Lightweighting is one of the most direct climate tools a CAD user has. DOE reports that a 10% lighter vehicle can get 6–8% better fuel economy, and EPA puts every gallon of gasoline at about 8,887 g of CO₂.',
                     'Designing for repair and recycling keeps materials in use; EPA describes sustainable materials management as a systematic approach to using and reusing materials more productively over their entire life cycles.'],
            'site': [('Physics I', 'Physics_I.html')],
            'src': [_DOEL, _EPAC]},
 'res': [(_DOEL[0], _DOEL[1], 'Lightweight materials data.'), (_EPAC[0], _EPAC[1], 'Vehicle CO₂ figures.'), (_SMM[0], _SMM[1], 'Life-cycle thinking.')]},
